'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v15',sprout:'M12 22v-9 M12 15C4 16 2 9 3 5c6 0 10 3 9 10z M12 12c-1-7 4-10 9-10 1 7-3 11-9 10',folder:'M3 7V4h7l2 3h9v14H3z',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 M14 6l6 6-6 6',back:'M20 12H4 M10 6l-6 6 6 6',menu:'M4 5h16v14H4z M9 5v14',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',star:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',close:'M6 6l12 12 M18 6 6 18',plus:'M12 4v16 M4 12h16',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pause:'M8 5v14 M16 5v14',check:'M4 12l5 5L20 6',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',network:'M12 3v7 M4 17v-7h16v7 M1 17h6v5H1z M9 17h6v5H9z M17 17h6v5h-6z M9 1h6v4H9z',leaf:'M4 20 18 6 M4 17C-1 5 11 2 21 3c0 12-5 20-17 14',file:'M5 2h10l5 5v15H5z M14 2v6h6 M8 13h9 M8 17h6',pet:'M5 8 3 2l7 4h4l7-4-2 6c6 10 1 14-7 14S-1 18 5 8z M7 13h1 M16 13h1 M10 17q2 2 4 0'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const key='zhiwen-v2.1'+(new URLSearchParams(location.search).has('test')?'-test':'');
const day=()=>new Date().toLocaleDateString('en-CA');
const defaults={difficulty:'中等',tone:'活泼',pet:true,push:true,time:'09:00',method:'桌宠气泡',scope:'全部课程'};
let state;try{state=JSON.parse(localStorage.getItem(key)||'null')}catch{}
state={settings:{...defaults,...state?.settings},records:state?.records||[],courses:state?.courses||[],session:state?.session||null,collapsed:state?.collapsed||false,reminded:state?.reminded||'',learned:state?.learned||{},dailyCompleted:state?.dailyCompleted||'',dailyPlan:state?.dailyPlan||null,courseStatus:state?.courseStatus||{},previousDailyDraft:state?.previousDailyDraft||null,deleted:state?.deleted||{},archivedSessions:state?.archivedSessions||[]};
if(state.session)state.session.paused=true;
let page='review',folder=null,filter='全部',query='',lastTick=Date.now(),modalFocus=null;
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('浏览器存储空间不足，请导出学习记录。')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200)}
function say(a,b,c){return state.settings.tone==='严肃'?a:state.settings.tone==='活泼'?b:c}
const make=(id,title,body,prompt,correct,dimension='记忆')=>({id,title,body,prompts:[prompt,`请用自己的话解释「${title}」的关键含义。`],correct,dimension,source:'记忆星球演示讲义 · '+title});
const network=[make('vpc','VPC 与子网','VPC 是逻辑隔离的虚拟网络，子网是其内部的地址范围划分。','VPC 和子网分别处于什么层级？','VPC 提供逻辑隔离的网络范围，子网是在 VPC 内对地址范围的进一步划分。','关联'),make('ip','私网与公网地址','私网地址用于私有网络范围，不能仅凭私网地址直接从公共互联网访问。','有私网 IP 就代表能从互联网直接访问吗？','不能。私网地址不具有直接的公网可达性，公网访问还取决于网络连接、地址转换与访问控制。','理解'),make('route','路由的作用','路由根据目的地址决定流量的下一跳或出口。','路由主要决定什么？它等同于访问许可吗？','路由决定流量的路径或下一跳，不等同于安全策略授权。','关联'),make('dns','DNS','DNS 可以把域名解析为地址。域名解析成功不代表应用服务一定正常。','域名解析成功能证明应用服务正常吗？','不能。DNS 解析仅是访问过程中的一环，还需要网络可达、端口可用与应用正常。','理解'),make('lb','负载均衡','负载均衡将流量分配到多个后端。健康检查帮助识别可用后端，但不意味着所有业务逻辑正常。','负载均衡与健康检查分别做什么？','负载均衡负责流量分配，健康检查按照配置的检查条件判断后端可用性。','记忆')];
const bio=[make('bio1','仿生学的研究思路','仿生设计研究生物的结构、功能与机制，再抽象出可用于工程设计的原理。','仿生设计为什么不只是模仿外形？','因为它关注结构背后的功能和机制，需要抽象原理并适配工程条件。','理解'),make('bio2','结构与功能','相似的功能可以由不同结构实现，观察到外形相似不足以证明作用机制相同。','外形相似能证明功能机制相同吗？','不能。还需要分析结构、材料、环境与作用机制。','理解'),make('bio3','尺度效应','尺寸改变时，面积与体积的变化比例不同，生物机制不能总是等比例放大。','为什么仿生结构不能总是直接等比例放大？','尺度变化会改变面积、体积及相关力学关系，需要重新检验机制的适用性。','关联'),make('bio4','观察与验证','观察生物现象用于提出假设，实验用于验证解释和设计效果。','观察到一个现象，是否已经证明其设计原理？','没有。观察支持提出假设，仍需实验检验机制及适用条件。','记忆'),make('bio5','抽象与迁移','生物系统中的机制需要经过抽象，再与工程约束匹配。','从生物现象到工程设计，中间需要哪些步骤？','分析机制、抽象原理、匹配工程约束，并通过实验验证。','关联')];
const base=[{id:'docker',title:'容器基础',english:'CONTAINERS, EXPLAINED',type:'公司培训',color:'#e5ebd8',symbol:'layers',desc:'从镜像到容器，建立清晰的概念关系。',concepts:DemoContent.map((x,i)=>({...x,dimension:['记忆','理解','关联'][i%3]}))},{id:'network',title:'云网络入门',english:'A CONNECTED WORLD',type:'公司培训',color:'#eee3d4',symbol:'network',desc:'串起地址、路由与网络服务。',concepts:network},{id:'bio',title:'仿生学初识',english:'LEARNING FROM NATURE',type:'个人学习',color:'#dfe8e4',symbol:'leaf',desc:'从自然的结构中，理解设计的原理。',concepts:bio}];
const courses=()=>[...base,...state.courses].filter(c=>!state.deleted[c.id]);
const course=id=>[...base,...state.courses].find(c=>c.id===id);
function evidence(c){const rs=state.records.filter(r=>r.course===c.id&&r.rating==='yes'&&!r.assisted);return new Set(rs.map(r=>r.concept)).size}
function layout(){const names={review:'我要复习',growth:'我的收获',library:'课程库',session:'温习进行中'};$('#app').innerHTML=`<div class="app-shell ${state.collapsed?'collapsed':''}"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('sprout')}</div><div class="brand-copy"><strong>记忆星球</strong><small>KEEP WHAT YOU LEARN</small></div></div><nav>${[['review','book'],['growth','sprout'],['library','folder']].map(([p,i])=>`<button class="nav-button ${page===p?'active':''}" data-action="nav" data-id="${p}" title="${names[p]}">${icon(i)}<span>${names[p]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="profile"><div class="avatar">lqy</div><div>lqy的学习空间</div><button class="profile-settings icon-button" data-action="settings" aria-label="设置" title="设置">${icon('gear')}</button></div></div></aside><div class="main"><header class="topbar"><div class="topbar-left"><button class="icon-button" data-action="collapse" aria-label="${state.collapsed?'展开':'收起'}侧栏">${icon('menu')}</button><span>${names[page]}</span></div><span class="demo-label">交互 Demo · 未接入 AI</span></header><main class="content" id="content"></main></div>${page!=='session'?`<div class="daily-float">${state.settings.pet?`<div class="pet">${icon('pet')}</div>`:''}<span class="daily-label">${dailyDone()?'今天的小挑战已完成':'每日小挑战 · 轻轻想一想'}</span><button class="toy" data-action="daily" aria-label="每日小挑战" title="每日小挑战">${icon('star')}</button></div>`:''}</div>`;renderContent()}
function heading(eyebrow,title,sub,action=''){return `<div class="heading-row"><div><h1>${title}</h1></div>${action}</div>`}
function renderContent(){if(page==='review'||page==='library')shelf();if(page==='growth')growth();if(page==='session')sessionView()}
function shelf(){if(page==='library'&&folder){folderView();return}const lib=page==='library';$('#content').innerHTML=heading(lib?'YOUR KNOWLEDGE, TOGETHER':'A LITTLE RECALL, EVERY DAY',lib?'课程库':'我要复习',lib?'资料与课程框架，整齐收在一起。':'选一本课程，把学过的知识再想起来。',lib?`<button class="btn primary" data-action="import">${icon('plus')}导入资料</button>`:'')+(!lib&&state.session?`<div class="banner"><div><h3>上次的温习，随时接着来</h3><p>${esc(state.session.title)} · 已答 ${state.session.index} / ${state.session.questions.length} 题</p></div><button class="btn primary" data-action="resume">继续温习 ${icon('arrow')}</button></div>`:'')+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="搜索课程" placeholder="搜索课程名称…" value="${esc(query)}"></label>${['全部','公司培训','个人学习'].map(x=>`<button class="chip ${filter===x?'active':''}" data-action="filter" data-id="${x}">${x}</button>`).join('')}</div><div class="bookshelf" id="books"></div>`;books()}
function books(){const lib=page==='library',list=courses().filter(c=>(filter==='全部'||c.type===filter)&&c.title.toLowerCase().includes(query.toLowerCase()));$('#books').innerHTML=list.map((c,i)=>{let count=evidence(c),total=c.concepts.length;return `<button class="course-card ${lib?'folder':''}" data-action="${lib?'folder':'choose'}" data-id="${c.id}"><div class="book-cover" style="--cover:${c.color}"><span class="number">${lib?'COURSE COLLECTION':'VOL. '+String(i+1).padStart(2,'0')}</span><h2>${esc(c.title)}</h2><div class="english">${esc(c.english||'PERSONAL COLLECTION')}</div><div class="cover-art">${icon(c.symbol||'book')}</div></div><div class="course-info"><div class="course-meta"><span>${c.type} · ${c.imported?'个人导入':'示例课程'}</span><span>${lib?(c.files?.length||1)+' 份材料':total+' 个知识点'}</span></div>${lib?`<div class="course-bottom"><span>${c.imported?'待提取 · 框架待确认':'课程框架已整理'}</span>${icon('arrow')}</div>`:`<div class="progress"><i style="width:${total?count/total*100:0}%"></i></div><div class="course-bottom"><span>${total?count+' / '+total+' 个有独立自评记录':'等待材料提取'}</span><span>开始温习 →</span></div>`}</div></button>`}).join('')||'<div class="empty">没有找到课程，换个关键词试试。</div>'}
function modal(title,body,wide=false){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}</section></div>`;$('#modal-root button')?.focus()}
function close(){ $('#modal-root').innerHTML='';if(modalFocus?.isConnected)modalFocus.focus() }
let selectedCount=5,chosen=null;
function pool(c,mode='review'){return [0,...(mode==='instant'?[]:[1])].flatMap(i=>c.concepts.filter(x=>x.prompts[i]).map(x=>({course:c.id,concept:x.id,prompt:x.prompts[i],correct:x.correct,source:x.source,url:x.url,dimension:x.dimension||'理解',type:i===0?'简答回忆':'换个角度',body:x.body}))) }
function choose(id){chosen=id;selectedCount=5;const c=course(id);if(!c.concepts.length){modal('课程准备中',`<p>原文件已归档。请先在课程库查看材料；此 Demo 尚未接入自动提取与出题，不会使用其他课程的题目替代。</p><div class="divider"></div><button class="btn primary full" data-action="go-folder" data-id="${id}">查看课程资料</button>`);return}modal(c.title,`<p>选一个适合今天的节奏。</p><div class="count-options">${[5,25,65].map((n,i)=>`<button class="count-option ${i===0?'selected':''}" data-action="count" data-id="${n}"><strong>${n}</strong><small>${['轻轻回顾','深入温习','完整检验'][i]}</small></button>`).join('')}</div><p id="count-note"></p><div class="divider"></div><button class="btn primary full" data-action="start-review">开始温习 ${icon('arrow')}</button><p class="notes">难度：${state.settings.difficulty} · 简答自评 · 途中可以暂停</p>`);countNote()}
function countNote(){const n=Math.min(selectedCount,pool(course(chosen)).length);$('#count-note').textContent=selectedCount>n?`本示例课程只有 ${n} 道不同题目，本次将练习 ${n} 题，不重复凑数。`:`本次 ${n} 题，预计 ${n*2} 分钟。`}
function order(qs){const rank={记忆:0,理解:1,关联:2};const d=state.settings.difficulty;return qs.sort((a,b)=>d==='简单'?rank[a.dimension]-rank[b.dimension]:d==='难'?rank[b.dimension]-rank[a.dimension]:0)}
function start(title,questions,mode){if(state.session){modal('继续，或开始新练习',`<p>已有一份暂停的练习。已提交的记录会保留；开始新的练习将替换未完成的进度。</p><div class="rating"><button class="btn" data-action="resume">继续上次</button><button class="btn primary" id="replace-session">开始新的练习</button></div>`);$('#replace-session').onclick=()=>{state.session=null;start(title,questions,mode)};return}state.session={id:crypto.randomUUID(),title,questions:order(questions),mode,index:0,seconds:0,paused:false,draft:'',revealed:false,assisted:false,rating:null,started:day(),results:[]};save();close();page='session';lastTick=Date.now();layout()}
function fmt(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function sessionView(){const s=state.session;if(!s){page='review';layout();return}const q=s.questions[s.index];$('#content').innerHTML=`<div class="session"><div class="session-top"><button class="back" data-action="leave-session">${icon('back')}保存并返回</button><span class="tag">${s.mode==='daily'?'每日小挑战':s.mode==='instant'?'课后即时练习':'课程温习'}</span></div><h2>${esc(s.title)}</h2><div class="session-top" style="margin-top:22px"><span class="muted">已答 ${s.index} / ${s.questions.length} 题</span><span class="muted">${icon('clock')} 已答时间 <b id="timer">${fmt(s.seconds)}</b>　<button class="btn" data-action="pause">${icon(s.paused?'arrow':'pause')}${s.paused?'继续':'暂停'}</button></span></div><div class="progress"><i style="width:${s.index/s.questions.length*100}%"></i></div>${s.paused?`<div class="panel question-panel paused">${icon('pause')}<h2>歇一会儿，进度在这里。</h2><p class="muted">计时已暂停，回来后继续。</p><button class="btn primary" data-action="pause">继续答题 ${icon('arrow')}</button></div>`:`<div class="panel question-panel"><span class="tag">${String(s.index+1).padStart(2,'0')} / ${s.questions.length}　${esc(q.type)} · ${q.dimension}</span><h2>${esc(q.prompt)}</h2><textarea id="draft" aria-label="你的回答" placeholder="试着用自己的话说清楚，不必追求完美。" ${s.revealed?'readonly':''}>${esc(s.draft)}</textarea>${s.revealed?`<div class="answer"><strong>参考答案</strong><p>${esc(q.correct)}</p>${q.url?`<a href="${esc(q.url)}" target="_blank" rel="noopener">来源：${esc(q.source)} ↗</a>`:`<small>来源：${esc(q.source)}</small>`}</div><p class="notes">${s.assisted?'本题提前查看答案，记为辅助练习，不增加独立掌握证据。':'请对照要点自评。Demo 不使用 AI 判分。'}</p><div class="rating">${[['no','还没记住'],['partial','记住一部分'],['yes','能独立说清']].map(([v,t])=>`<button class="btn ${s.rating===v?'selected':''}" data-action="rate" data-id="${v}">${t}</button>`).join('')}</div>`:''}<div class="session-actions">${s.revealed?`<button class="btn text" data-action="dispute">反馈题目问题</button><button class="btn primary" data-action="next" ${!s.rating?'disabled':''}>${s.index===s.questions.length-1?'完成本次练习':'下一题'} ${icon('arrow')}</button>`:`<button class="btn text" data-action="reveal">立刻查看答案</button><button class="btn primary" data-action="submit" ${!s.draft.trim()?'disabled':''}>提交回答 ${icon('arrow')}</button>`}</div></div><p class="notes">${say('独立回忆后核对答案，可形成更清楚的学习记录。','慢慢想，小羊陪你。想不起来也可以看看答案。','先尝试回忆，再对照答案检查遗漏。')}</p>`}</div>`}
function tick(){const now=Date.now(),s=state.session;if(s&&page==='session'&&!s.paused){s.seconds+=Math.max(0,Math.round((now-lastTick)/1000));if($('#timer'))$('#timer').textContent=fmt(s.seconds);if(s.mode==='daily'&&s.seconds>=900&&!s.budgetShown){s.budgetShown=true;s.paused=true;save();sessionView();modal('今天的 15 分钟，已经很充实',`<p>已完成的回答都会保留。可以收好今天的成果，未完成任务不形成欠账。</p><div class="divider"></div><button class="btn primary full" data-action="finish-daily">今天到这里</button>`)}save()}lastTick=now;remind()}
function next(){const s=state.session;if(!s.rating||s.paused)return;const q=s.questions[s.index];const r={id:s.id+'-'+s.index,session:s.id,date:day(),at:new Date().toISOString(),course:q.course,concept:q.concept,dimension:q.dimension,prompt:q.prompt,answer:s.draft,rating:s.rating,assisted:s.assisted,mode:s.mode,seconds:s.seconds};if(!state.records.some(x=>x.id===r.id))state.records.push(r);s.results.push(r);s.index++;s.draft='';s.revealed=false;s.assisted=false;s.rating=null;if(s.index===s.questions.length){const total=s.questions.length,yes=s.results.filter(x=>x.rating==='yes'&&!x.assisted).length,time=fmt(s.seconds),mode=s.mode;if(mode==='daily')state.dailyCompleted=day();state.session=null;save();page='growth';layout();modal('今天又留住了一点',`<div class="result"><div class="result-icon">${icon('sprout')}</div><h2>${say('本次练习已完成','给认真回想的你，一片新叶。','这次回忆已记录。')}</h2><p>${total} 道练习 · 用时 ${time}<br>${yes} 道自评独立说清，其余内容将继续温习。</p><button class="btn primary full" data-action="close">看看我的收获</button></div>`)}else{save();sessionView()}}
function dailyDone(){return state.dailyCompleted===day()}
function dailyPool(){if(dailyDone())return [];const done=new Set(state.records.filter(r=>r.date===day()).map(r=>r.concept));if(state.dailyPlan?.date===day()&&state.dailyPlan.scope===state.settings.scope)return state.dailyPlan.questions.filter(q=>!done.has(q.concept));let cs=courses().filter(c=>!c.imported&&(state.settings.scope==='全部课程'||c.type===state.settings.scope));let qs=cs.flatMap(c=>pool(c,'instant'));const score=q=>{const rs=state.records.filter(r=>r.concept===q.concept&&!r.assisted&&r.rating==='yes');return new Set(rs.map(r=>r.date)).size};qs.sort((a,b)=>score(a)-score(b));const questions=qs.filter(q=>!done.has(q.concept)).slice(0,10).map((q,i)=>({...q,type:['一句话小老师','旧知识重逢','概念小侦探'][i%3]}));state.dailyPlan={date:day(),scope:state.settings.scope,questions};save();return questions}
function daily(){if(state.session?.mode==='daily'){close();page='session';layout();return}const qs=dailyPool();modal('今天的小挑战',`<div class="result"><div class="result-icon">${icon('star')}</div><h2>${qs.length?'给记忆浇一点水。':'今天已经够了。'}</h2><p>${qs.length?`${qs.length} 个小任务 · 约 ${Math.min(15,qs.length+3)} 分钟<br>优先回顾记录较少的知识，今天练过的不重复推送。`:'今天范围内的内容已经练过了，明天再见。'}</p>${qs.length?'<button class="btn primary full" id="begin-daily">开始每日挑战</button>':'<button class="btn primary full" data-action="close">好，今天到这里</button>'}<p class="notes">每天重新安排，不积攒昨日任务。示例课程视为已学习。</p></div>`);if(qs.length)$('#begin-daily').onclick=()=>start('每日小挑战',qs,'daily')}
function growth(){const rs=state.records,ind=rs.filter(r=>r.rating==='yes'&&!r.assisted&&!r.objective),days=new Set(rs.map(r=>r.date)),concepts=new Set(ind.map(r=>r.concept));const stable=new Set([...concepts].filter(id=>new Set(ind.filter(r=>r.concept===id).map(r=>r.date)).size>=2));$('#content').innerHTML=heading('EVERY SMALL STEP COUNTS','我的收获','每一次认真回想，都有迹可循。',`<button class="btn" data-action="export">导出记录 ${icon('arrow')}</button>`)+`<div class="stats"><div class="stat"><small>有效练习</small><strong>${rs.length}<small> 次</small></strong></div><div class="stat"><small>独立自评说清</small><strong>${concepts.size}<small> 个知识点</small></strong></div><div class="stat"><small>跨天再次说清</small><strong>${stable.size}<small> 个知识点</small></strong></div></div><div class="split"><section class="panel"><div class="section-title"><h3>知识，慢慢长出新叶</h3>${icon('sprout')}</div>${['记忆','理解','关联'].map(d=>{const total=[...base,...state.courses].flatMap(c=>c.concepts).filter(x=>x.dimension===d).length,ids=new Set(ind.filter(r=>r.dimension===d).map(r=>r.concept)),n=ids.size;return `<div class="level-row"><div><span>${d}</span><span class="muted">${n?'初步记录':'待验证'} · ${n} / ${total}</span></div><div class="progress"><i style="width:${total?n/total*100:0}%"></i></div></div>`}).join('')}<p class="notes">进度条表示示例知识点的独立自评覆盖，不是 AI 认证的掌握百分比。跨天记录与即时练习分开保留。</p></section><section class="panel"><div class="section-title"><h3>我的学习足迹</h3><span class="tag">${days.size} 个学习日</span></div>${rs.length?courses().filter(c=>rs.some(r=>r.course===c.id)).map(c=>`<div class="history-row"><div>${esc(c.title)}<small>${rs.filter(r=>r.course===c.id).length} 次回答 · ${evidence(c)} 个知识点独立自评说清</small></div><button class="btn text" data-action="choose" data-id="${c.id}">再温习 →</button></div>`).join(''):'<div class="empty">第一片新叶，等你来种下。<br><button class="btn text" data-action="nav" data-id="review">去做一次小温习 →</button></div>'}</section></div><section class="panel" style="margin-top:24px"><div class="section-title"><h3>最近的回想</h3></div>${rs.length?rs.slice().reverse().slice(0,30).map(r=>`<div class="history-row"><div><strong>${esc(r.prompt)}</strong><small>${esc(course(r.course)?.title)} · ${esc(r.date)} · ${r.mode==='daily'?'每日挑战':r.mode==='instant'?'即时练习':'课程温习'}</small><div class="muted" style="margin-top:7px">${esc(r.answer||'未作答，直接查看答案')}</div></div><span class="tag" style="height:fit-content;white-space:nowrap">${r.objective?(r.rating==='yes'?'趣味题答对':'趣味题待巩固'):r.assisted?'辅助练习':{yes:'独立自评说清',partial:'仍有遗漏',no:'需要温习'}[r.rating]}</span></div>`).join(''):'<div class="empty">还没有记录。完成练习后，会在这里留下你的回答。</div>'}</section>`}
function folderView(){const c=course(folder);$('#content').innerHTML=`<button class="back" data-action="folder-back">${icon('back')}返回课程库</button>`+heading('COURSE COLLECTION',esc(c.title),c.imported?'原文件已在当前浏览器归档；提取与出题待接入。':c.desc,`<button class="btn primary" data-action="instant" data-id="${c.id}" ${c.concepts.length?'':'disabled'}>学习完毕 ${icon('check')}</button>`)+`<div class="split"><section class="panel"><div class="section-title"><h3>原始资料</h3><span class="tag">${c.type}</span></div>${c.imported?c.files.map(f=>`<div class="file-row"><div class="file-icon">${icon('file')}</div><div class="file-name">${esc(f.name)}<small>${(f.size/1024).toFixed(1)} KB · 本地归档</small></div><button class="btn text" data-action="download-file" data-id="${f.id}">下载</button></div>`).join(''):`<div class="file-row"><div class="file-icon">${icon('file')}</div><div class="file-name">${esc(c.title)} · 演示讲义.txt<small>内置示例 · 非公司真实培训材料</small></div><button class="btn text" data-action="read" data-id="${c.id}">阅读</button><button class="btn text" data-action="sample-download" data-id="${c.id}">下载</button></div>`}<p class="notes">Demo 不上传文件。PPT、PDF、视频可归档，但尚未自动提取。</p></section><section class="panel"><div class="section-title"><h3>课程框架</h3><span class="tag">${c.imported?'待确认':'示例框架'}</span></div>${c.concepts.length?c.concepts.map((x,i)=>`<div class="tree-item"><strong>${String(i+1).padStart(2,'0')}　${esc(x.title)}</strong><p>${esc(x.subtitle||x.body)}</p></div>`).join(''):c.headings?.length?c.headings.map(x=>`<div class="tree-item">${esc(x)}</div>`).join(''):'<div class="empty">材料已收好。<br>此格式尚未提取，不生成猜测性的课程框架。</div>'}${c.imported?'<p class="notes">文本文件仅提取 Markdown 标题作为草稿，不代表知识提取完成。</p>':''}</section></div>`}
const lecture=c=>c.concepts.map(x=>`# ${x.title}\n\n${x.body}\n\n来源：${x.source}${x.url?'\n'+x.url:''}`).join('\n\n');
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('zhiwen-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function filesWrite(items){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite');items.forEach(x=>tx.objectStore('files').put(x.file,x.id));tx.oncomplete=()=>{d.close();resolve()};tx.onerror=()=>{d.close();reject(tx.error)}})}
async function fileRead(id){const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>{d.close();resolve(r.result)};r.onerror=()=>{d.close();reject(r.error)}})}
function importModal(){modal('收好一门新课程',`<form id="import-form"><div class="field"><label for="course-name">课程名称</label><input id="course-name" required maxlength="60" placeholder="例如：仿生学基础"></div><div class="field"><label for="course-type">资料归属</label><select id="course-type"><option>个人学习</option><option>公司培训</option></select></div><div class="field"><label for="course-files">课程资料（可多选，合计不超过 50 MB）</label><input id="course-files" type="file" multiple required accept=".txt,.md,.pdf,.ppt,.pptx,.doc,.docx,.mp4,.srt,.vtt"></div><p>文件保存在当前浏览器中，不上传。公司资料请确认允许在此设备保存。本 Demo 仅归档文件，文本标题可形成框架草稿。</p><div class="divider"></div><button class="btn primary full" type="submit">导入并收纳</button></form>`);$('#import-form').onsubmit=async e=>{e.preventDefault();const files=[...$('#course-files').files],title=$('#course-name').value.trim(),type=$('#course-type').value;if(!title||!files.length)return;if(files.reduce((n,f)=>n+f.size,0)>50*1024*1024){toast('本次文件超过 50 MB，请减少文件后再导入。');return}const button=e.submitter;button.disabled=true;button.textContent='正在保存…';try{const items=files.map(file=>({file,id:crypto.randomUUID()}));await filesWrite(items);const headings=[];for(const f of files.filter(f=>/\.(txt|md)$/i.test(f.name))){const text=await f.text();headings.push(...text.split(/\r?\n/).filter(l=>/^#{1,3}\s/.test(l)).map(l=>l.replace(/^#+\s*/,'')))}const c={id:crypto.randomUUID(),title,type,files:items.map(x=>({id:x.id,name:x.file.name,size:x.file.size})),headings:headings.slice(0,30),concepts:[],color:'#e6e8dc',symbol:'folder',imported:true};state.courses.push(c);save();close();page='library';folder=c.id;layout();toast('原文件已归档，课程文件夹已建立。')}catch{toast('保存失败，浏览器可能不支持本地文件存储。');button.disabled=false;button.textContent='重新导入'}}}
let settingsDraft;
function settings(){settingsDraft={...state.settings};modal('按你的节奏来',`<div class="setting-row"><div>练习难度<small>调整题目优先顺序</small></div><div class="segmented">${['简单','中等','难'].map(x=>`<button data-action="setting" data-key="difficulty" data-id="${x}" class="${settingsDraft.difficulty===x?'selected':''}">${x}</button>`).join('')}</div></div><div class="setting-row"><div>陪伴语气<small>只影响鼓励语，不改变评价标准</small></div><div class="segmented">${['严肃','活泼','中性'].map(x=>`<button data-action="setting" data-key="tone" data-id="${x}" class="${settingsDraft.tone===x?'selected':''}">${x}</button>`).join('')}</div></div><div class="divider"></div><div class="setting-row"><label for="pet-setting">显示桌宠小羊<small>关闭后保留每日挑战宝石</small></label><input id="pet-setting" type="checkbox" ${settingsDraft.pet?'checked':''}></div><div class="setting-row"><label for="push-setting">每日挑战提醒</label><input id="push-setting" type="checkbox" ${settingsDraft.push?'checked':''}></div><div class="setting-row"><label for="push-time">推送时间</label><input id="push-time" type="time" value="${settingsDraft.time}" required></div><div class="setting-row"><label for="push-method">推送方式</label><select id="push-method">${['桌宠气泡','页面弹窗'].map(x=>`<option ${settingsDraft.method===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="setting-row"><label for="push-scope">参与每日挑战</label><select id="push-scope">${['全部课程','公司培训','个人学习'].map(x=>`<option ${settingsDraft.scope===x?'selected':''}>${x}</option>`).join('')}</select></div><p class="notes">网页打开且到达设置时间时，每天提醒一次。关闭网页后的系统推送与桌面自启需后续桌面版支持。</p><div class="divider"></div><button class="btn primary full" data-action="save-settings">保存设置</button><button class="btn text full" data-action="preview-push">预览提醒效果</button>`)}
function remind(){const d=new Date(),now=`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;if(state.settings.push&&state.reminded!==day()&&now>=state.settings.time&&page!=='session'&&!$('#modal-root').innerHTML&&document.visibilityState==='visible'){state.reminded=day();save();if(state.settings.method==='页面弹窗')daily();else toast(say('今日温习任务已准备，可点击右下角入口。','小羊带着今天的小挑战来了，点点右下角宝石吧。','每日挑战已准备好，点击右下角开始。'))}}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;books()}if(e.target.id==='draft'){state.session.draft=e.target.value;const b=$('[data-action="submit"]');if(b)b.disabled=!e.target.value.trim();save()}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id}=b.dataset;
if(a==='nav'){if(state.session){state.session.paused=true;save()}page=id;folder=null;query='';filter='全部';close();layout()}
if(a==='collapse'){state.collapsed=!state.collapsed;save();layout()}
if(a==='filter'){filter=id;shelf()}
if(a==='choose')choose(id);
if(a==='count'){selectedCount=Number(id);document.querySelectorAll('.count-option').forEach(x=>x.classList.toggle('selected',x===b));countNote()}
if(a==='start-review')start(course(chosen).title,order(pool(course(chosen))).slice(0,selectedCount),'review');
if(a==='close')close();
if(a==='resume'){close();page='session';state.session.paused=false;lastTick=Date.now();save();layout()}
if(a==='pause'){state.session.paused=!state.session.paused;lastTick=Date.now();save();sessionView()}
if(a==='leave-session'){state.session.paused=true;save();page='review';layout()}
if(a==='reveal'||a==='submit'){if(a==='submit'&&!state.session.draft.trim())return;state.session.revealed=true;state.session.assisted=a==='reveal';save();sessionView()}
if(a==='rate'){state.session.rating=id;save();sessionView()}
if(a==='next')next();
if(a==='finish-daily'){state.dailyCompleted=day();state.session=null;save();close();page='growth';layout();toast('今天的成果已收好，明天重新安排。')}
if(a==='dispute'){state.session.assisted=true;state.session.rating='no';save();toast('本题已标记有异议，不计入独立掌握记录。');sessionView()}
if(a==='daily')daily();
if(a==='settings')settings();
if(a==='setting'){settingsDraft[b.dataset.key]=id;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b))}
if(a==='save-settings'){if(!$('#push-time').value){toast('请选择提醒时间');return}state.settings={...settingsDraft,pet:$('#pet-setting').checked,push:$('#push-setting').checked,time:$('#push-time').value,method:$('#push-method').value,scope:$('#push-scope').value};save();close();layout();toast('设置已保存，按你的节奏来。')}
if(a==='preview-push'){const method=$('#push-method').value;close();if(method==='页面弹窗')daily();else toast('小羊：今天的小挑战准备好了，点点右下角宝石。')}
if(a==='folder'||a==='go-folder'){close();folder=id;page='library';layout()}
if(a==='folder-back'){folder=null;shelf()}
if(a==='read')modal(course(id).title,`<div class="source-text">${esc(lecture(course(id)))}</div><div class="divider"></div><button class="btn primary full" data-action="instant" data-id="${id}">学习完毕，回忆一下</button>`,true);
if(a==='instant'){const c=course(id);state.learned[id]=day();save();start(c.title+' · 课后回忆',pool(c,'instant').slice(0,10),'instant')}
if(a==='import')importModal();
if(a==='sample-download')download(course(id).title+'-演示讲义.txt',new Blob([lecture(course(id))],{type:'text/plain;charset=utf-8'}));
if(a==='download-file'){try{const f=await fileRead(id);if(f)download(f.name,f);else toast('文件不存在，请重新导入原文件。')}catch{toast('读取失败，请检查浏览器存储。')}}
if(a==='export')download('记忆星球-学习记录.json',new Blob([JSON.stringify({exportedAt:new Date().toISOString(),records:state.records,settings:state.settings},null,2)],{type:'application/json'}));
});
document.addEventListener('keydown',e=>{if(!$('#modal-root').innerHTML)return;if(e.key==='Escape')close();if(e.key==='Tab'){const list=[...$('#modal-root').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.session){state.session.paused=true;save();if(page==='session')sessionView()}});
window.addEventListener('beforeunload',()=>{if(state.session)state.session.paused=true;save()});
layout();setInterval(tick,1000);

/* v3: course lifecycle, link sources, sheep companion and objective challenges. */
state.courseStatus=state.courseStatus||{};


const statusOf=c=>state.courseStatus[c.id]||c.status||(c.imported?'learning':'completed');
function setCourseStatus(id,status){if(!course(id))return;state.courseStatus[id]=status;save()}
function sourceUrl(raw){try{const u=new URL(raw.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();return u.href}catch{throw Error('请填写完整的 http 或 https 课程链接。')}}
function sourceKind(url){const host=new URL(url).hostname;if(/(^|\.)(kdocs\.cn|wps\.cn|wps\.com)$/.test(host))return 'WPS 云文档';if(/(^|\.)(bilibili\.com|b23\.tv)$/.test(host))return 'B 站网课';return '网页资料'}
function newCourse(title,type,links=[],files=[],headings=[]){const c={id:crypto.randomUUID(),title,type,status:'learning',links:links.map(url=>({url,kind:sourceKind(url),status:'pending'})),files,headings,concepts:[],color:'#e6e8dc',symbol:'folder',imported:true};state.courses.push(c);save();return c}
const sheep=()=>`<svg class="sheep-art" viewBox="0 0 120 124" role="img" aria-label="新疆小羊风格桌宠"><ellipse cx="60" cy="113" rx="34" ry="6" fill="#d7daca" opacity=".5"/><path d="M42 94v15m36-15v15" stroke="#665448" stroke-width="9" stroke-linecap="round"/><path d="M34 69c-16-5-17 19-4 23-3 16 18 20 23 12 12 12 28 3 27-5 17 0 23-20 9-25 3-20-15-24-24-17-8-14-30-9-31 12Z" fill="#fffaf0" stroke="#d4c6ac" stroke-width="2"/><path d="M31 39C3 27 8 66 32 60M89 39c28-12 23 27-1 21" fill="#ac8065" stroke="#775c48" stroke-width="2"/><path d="M28 40c-12 0-12 12-4 12m69-12c12 0 12 12 4 12" fill="none" stroke="#e6c39b" stroke-width="3"/><path d="M39 49 21 60l18 8m42-19 18 11-18 8" fill="#8d705b"/><ellipse cx="60" cy="61" rx="28" ry="30" fill="#b69172"/><path d="M31 43c-7-10 0-19 9-17-2-13 13-18 20-10 11-10 25-2 23 9 13-1 18 15 7 22-8-3-12-9-15-13-6 12-14 8-18 3-8 12-21 13-26 6Z" fill="#fffaf0" stroke="#d4c6ac" stroke-width="2"/><ellipse cx="49" cy="61" rx="3" ry="4" fill="#362e2b"/><ellipse cx="72" cy="61" rx="3" ry="4" fill="#362e2b"/><ellipse cx="60" cy="73" rx="4" ry="3" fill="#5f4438"/><path d="M60 76v3m-7-1q7 8 14 0" stroke="#624b3c" stroke-width="2" fill="none"/><ellipse cx="40" cy="71" rx="5" ry="3" fill="#df987c" opacity=".6"/><ellipse cx="81" cy="71" rx="5" ry="3" fill="#df987c" opacity=".6"/><path d="M36 88q24 14 48 0l-7 12-17-5-16 6Z" fill="#92a17c"/><path d="m53 92 7 5 7-5-7-5Z" fill="#f8e6be"/></svg>`;
const gem=()=>`<span class="gem-spark spark-one">✦</span><span class="gem-spark spark-two">✧</span><svg class="gem-art" viewBox="0 0 80 80" aria-hidden="true"><defs><linearGradient id="gem-gradient" x2="1" y2="1"><stop stop-color="#d4f1e7"/><stop offset=".5" stop-color="#76b7a4"/><stop offset="1" stop-color="#457f77"/></linearGradient></defs><path d="m22 13 36 0 15 21-33 37L7 34Z" fill="url(#gem-gradient)" stroke="#5c9081" stroke-width="1.5"/><path d="m22 13 18 58 18-58M7 34h66M22 13l18 21 18-21" stroke="#edfff2" stroke-width="1.3" fill="none" opacity=".8"/><path d="m12 31 12-14h14L28 31Z" fill="#fff" opacity=".5"/></svg><span class="gem-shadow"></span>`;
const originalLayout=layout;
layout=function(){originalLayout();const nav=$('.sidebar nav');nav.insertAdjacentHTML('afterbegin',`<button class="nav-button ${page==='recent'?'active':''}" data-action="nav" data-id="recent" title="最近在学">${icon('leaf')}<span>最近在学</span></button>`);if(page==='recent')$('.topbar-left span').textContent='最近在学';const pet=$('.pet');if(pet){pet.innerHTML=sheep();pet.classList.add('sheep-pet')}const toy=$('.toy');if(toy){toy.innerHTML=gem();toy.classList.add('gem-toy');toy.title='小羊的宝石 · 每日挑战'} };
const originalRender=renderContent;
renderContent=function(){if(page==='recent')shelf();else originalRender()};
shelf=function(){if((page==='library'||page==='recent')&&folder){folderView();return}const recent=page==='recent',lib=page==='library';$('#content').innerHTML=heading(recent?'MAKE ROOM FOR SOMETHING NEW':lib?'YOUR KNOWLEDGE, TOGETHER':'A LITTLE RECALL, EVERY DAY',recent?'最近在学':lib?'课程库':'我要复习',recent?'把想学的放在这里，一门一门，慢慢学。':lib?'学习中与已学完的课程，都好好收在这里。':'选一本课程，把学过的知识再想起来。',recent?`<button class="btn primary" data-action="import">${icon('plus')}新建课程</button>`:'')+(page==='review'&&state.session?`<div class="banner"><div><h3>上次的练习，随时接着来</h3><p>${esc(state.session.title)} · 已答 ${state.session.index} / ${state.session.questions.length} 题</p></div><button class="btn primary" data-action="resume">继续练习 ${icon('arrow')}</button></div>`:'')+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="搜索课程" placeholder="搜索课程名称…" value="${esc(query)}"></label>${['全部','公司培训','个人学习'].map(x=>`<button class="chip ${filter===x?'active':''}" data-action="filter" data-id="${x}">${x}</button>`).join('')}</div><div class="bookshelf" id="books"></div>`;books()};
books=function(){const recent=page==='recent',lib=page==='library';const list=courses().filter(c=>(!recent||statusOf(c)==='learning')&&(filter==='全部'||c.type===filter)&&c.title.toLowerCase().includes(query.toLowerCase()));$('#books').innerHTML=list.map((c,i)=>{const total=c.concepts.length,count=evidence(c),status=statusOf(c)==='learning'?'学习中':'已学习';return `<article class="course-wrap"><button class="course-card ${lib?'folder':''}" data-action="${recent?'recent-folder':lib?'folder':'choose'}" data-id="${c.id}"><div class="book-cover" style="--cover:${c.color}"><span class="number">${lib?'COURSE COLLECTION':'VOL. '+String(i+1).padStart(2,'0')}</span><h2>${esc(c.title)}</h2><div class="english">${esc(c.english||'ONE COURSE, ONE SMALL STEP')}</div><div class="cover-art">${icon(c.symbol||'book')}</div></div><div class="course-info"><div class="course-meta"><span>${esc(c.type)}</span><span class="status-tag ${statusOf(c)}">${status}</span></div>${recent||lib?`<div class="course-bottom"><span>${c.links?.length||0} 个链接 · ${c.imported?c.files?.length||0:1} 份文件</span><span>${recent?'':'打开文件夹 →'}</span></div>`:`<div class="progress"><i style="width:${total?count/total*100:0}%"></i></div><div class="course-bottom"><span>${total?count+' / '+total+' 个独立自评记录':'材料待整理'}</span><span>温习 →</span></div>`}</div></button><button class="course-delete" data-action="delete-course" data-id="${c.id}" aria-label="删除课程" title="删除课程">×</button></article>`}).join('')||`<div class="empty empty-shelf">${icon('leaf')}<h3>${recent&&!query?'这里留给你下一门想学的课。':'没有找到课程。'}</h3><p>${recent?'贴上 WPS 云文档或网课链接，就能开始收纳。':'试试其他关键词或分类。'}</p>${recent?'<button class="btn primary" data-action="import">新建课程</button>':''}</div>`};
folderView=function(){const c=course(folder);$('#content').innerHTML=`<button class="back" data-action="folder-back">${icon('back')}返回${page==='recent'?'最近在学':'课程库'}</button>`+heading('COURSE COLLECTION',esc(c.title),`${c.type} · ${statusOf(c)==='learning'?'学习中':'已学完'}`,statusOf(c)==='learning'?`<button class="btn primary" data-action="complete-course" data-id="${c.id}">已学完 ${icon('check')}</button>`:`<button class="btn" data-action="reopen-course" data-id="${c.id}">重新学习</button>`)+`<div class="split"><section class="panel"><div class="section-title"><h3>课程资料</h3><span class="tag">原文件与来源</span></div>${(c.links||[]).map((l,i)=>`<div class="link-source"><div class="source-head"><span class="tag">${esc(l.kind)}</span><span class="muted">${l.capture?'已读取片段 · 待确认':'待浏览器读取'}</span></div><a class="source-link" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.capture?.title||l.title||l.url)} ↗</a><div class="source-actions"><button class="btn" data-action="read-link" data-id="${c.id}" data-index="${i}">课程内容读取</button>${l.capture?`<button class="btn text" data-action="capture-preview" data-id="${c.id}" data-index="${i}">查看已读内容</button>`:''}</div></div>`).join('')}${c.imported?(c.files||[]).map(f=>`<div class="file-row"><span class="file-icon">${icon('file')}</span><div class="file-name">${esc(f.name)}<small>${(f.size/1024).toFixed(1)} KB · 本地原件</small></div><button class="btn text" data-action="download-file" data-id="${f.id}">下载</button></div>`).join(''):`<div class="file-row"><span class="file-icon">${icon('file')}</span><div class="file-name">${esc(c.title)} · 演示讲义<small>内置示例材料</small></div><button class="btn text" data-action="read" data-id="${c.id}">阅读</button></div>`}<p class="notes">链接仅保存来源，读取成功后才会出现内容。内部资料默认在本机收纳。</p>${c.concepts.length?`<button class="btn green full" data-action="instant" data-id="${c.id}" style="margin-top:18px">练一练刚学的内容</button>`:''}</section><section class="panel"><div class="section-title"><h3>课程框架</h3><span class="tag">${c.imported?'草稿待确认':'示例框架'}</span></div>${c.concepts.length?c.concepts.map(x=>`<div class="tree-item"><strong>${esc(x.title)}</strong><p>${esc(x.subtitle||x.body)}</p></div>`).join(''):c.headings?.length?c.headings.map(x=>`<div class="tree-item">${esc(x)}</div>`).join(''):'<div class="empty">资料先收好，框架慢慢长出来。<p>等待正文或字幕读取，不依据链接标题猜课程内容。</p></div>'}</section></div>`};
importModal=function(){modal('开始一门新课程',`<form id="import-form"><div class="field"><label for="course-name">课程名称</label><input id="course-name" required maxlength="60" placeholder="例如：云网络基础 / 仿生学入门"></div><div class="field"><label for="course-links">课程链接 <small>B 站课程粘贴其中一集即可</small></label><textarea id="course-links" rows="3" placeholder="https://www.kdocs.cn/l/…&#10;https://www.bilibili.com/video/…"></textarea></div><div class="field"><label for="course-type">资料归属</label><select id="course-type"><option>个人学习</option><option>公司培训</option></select></div><details><summary>也可以添加本地文件</summary><div class="field"><label for="course-files">附件（可选，合计不超过 50 MB）</label><input id="course-files" type="file" multiple accept=".txt,.md,.pdf,.ppt,.pptx,.doc,.docx,.mp4,.srt,.vtt"></div></details><p class="notes">创建后自动设为学习中，同时收纳到课程库。链接不会自动上传到外部 AI。</p><div class="divider"></div><button class="btn primary full" type="submit">创建课程，开始学习 ${icon('arrow')}</button><p id="import-error" role="alert"></p></form>`);$('#import-form').onsubmit=async e=>{e.preventDefault();const title=$('#course-name').value.trim(),type=$('#course-type').value,files=[...$('#course-files').files];try{const links=[...new Set($('#course-links').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(sourceUrl))];if(!title)throw Error('请填写课程名称。');if(!links.length&&!files.length)throw Error('至少添加一个课程链接或一份文件。');if(links.length>500)throw Error('每门课程本次最多添加 500 个链接。');if(files.reduce((n,f)=>n+f.size,0)>50*1024*1024)throw Error('文件合计超过 50 MB。');e.submitter.disabled=true;const items=files.map(file=>({file,id:crypto.randomUUID()}));if(items.length)await filesWrite(items);const headings=[];for(const f of files.filter(f=>/\.(txt|md)$/i.test(f.name))){headings.push(...(await f.text()).split(/\r?\n/).filter(x=>/^#{1,3}\s/.test(x)).map(x=>x.replace(/^#+\s*/,'')))}newCourse(title,type,links,items.map(x=>({id:x.id,name:x.file.name,size:x.file.size})),headings.slice(0,30));close();page='recent';folder=null;query='';filter='全部';layout();toast('课程已设为学习中，也已收进课程库。')}catch(err){$('#import-error').textContent=err.message||'保存失败，请重试。';e.submitter.disabled=false}}};
function readerModal(id,index){const c=course(id),l=c.links[index];modal('让记忆星球读懂课程',`<span class="tag">${esc(l.kind)}</span><p style="margin-top:12px">保存链接只是记住课程地址；要生成框架和题目，还需要读取讲义正文或视频字幕。目前 Demo 尚未自动完成这一步，你可以先打开课程学习。</p><a class="btn green full" style="margin:18px 0" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">打开课程来源 ↗</a><details><summary>高级：使用实验性浏览器读取扩展</summary><p class="notes">这是开发验证用的手动通道，不是日常学习必须完成的操作。正式流程应由 Agent 自动读取。</p><ol class="reader-steps"><li>在浏览器加载本项目 reader-extension 文件夹中的扩展。</li><li>打开来源页面，点击扩展“读取当前内容”，检查预览后导出读取文件。</li><li>将读取文件接入本课程。只保存实际读到的片段。</li></ol><div class="field"><label for="capture-file">接入读取结果（.json）</label><input id="capture-file" type="file" accept=".json"></div><p class="notes">扩展尚未安装。此 Demo 未接入自动浏览 Agent。WPS 的画布或受限内容可能无法读取；B 站页面简介不是视频正文，请选中已显示字幕或补充字幕文件。</p><p id="capture-message" role="status"></p></details>`);$('#capture-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)throw Error('读取文件不能超过 1 MB。');const capture=validateCapture(JSON.parse(await f.text()),l.url);l.capture=capture;l.status='partial';c.headings=[...new Set([...(c.headings||[]),...capture.headings])].slice(0,60);save();close();folderView();toast('已保存实际读取的片段，请检查覆盖范围。')}catch(err){$('#capture-message').textContent=err.message||'读取文件格式有误。'}}}
function validateCapture(data,expected){if(data?.kind!=='zhiwen-page-capture'||data.version!==1||typeof data.text!=='string'||!data.text.trim())throw Error('没有有效的页面读取内容。');if(sourceUrl(data.url)!==sourceUrl(expected))throw Error('读取文件的来源链接与本课程不一致，请在对应页面重新读取。');if(data.text.length>150000)throw Error('读取片段过长，请分段读取。');return {url:sourceUrl(data.url),title:String(data.title||'读取片段').slice(0,200),text:data.text,headings:Array.isArray(data.headings)?data.headings.filter(x=>typeof x==='string').slice(0,60).map(x=>x.slice(0,200)):[],coverage:String(data.coverage||'页面可见片段'),capturedAt:String(data.capturedAt||''),method:String(data.method||'browser')};}

const games=[
 {id:'image',course:'docker',kind:'match',title:'给知识找搭档',prompt:'把两张概念卡送回正确的位置。',left:['镜像','容器'],right:['运行实例，有自己的状态','用于创建实例的只读模板'],answer:[1,0],explain:'镜像提供模板，容器是基于镜像创建的实例。'},
 {id:'lifecycle',course:'docker',kind:'choice',title:'捉住一句小错误',prompt:'小羊的笔记里，哪句话写错了？',options:['停止容器不等于删除它','停止容器就会删除所有外部数据','删除容器会移除其可写层'],answer:1,explain:'停止与删除不同；外部存储的去留也要单独判断。'},
 {id:'isolation',course:'docker',kind:'choice',title:'真假小侦探',prompt:'常见 Linux 容器共享宿主内核，因此“有隔离”不等于“绝对安全”。',options:['这个说法成立','这个说法不成立'],answer:0,explain:'常见 Linux 容器共享内核。隔离提供边界，但不是绝对安全的保证。'},
 {id:'storage',course:'docker',kind:'choice',title:'补上关键拼图',prompt:'判断删除容器后数据是否还在，先看数据存放在 ______。',options:['哪个位置、使用哪种存储','哪一个镜像名称','哪一天创建的容器'],answer:0,explain:'可写层与独立存储生命周期不同，不能仅凭容器删除判断所有数据。'},
 {id:'vpc',course:'network',kind:'match',title:'概念配对小站',prompt:'给两个网络概念找到合适的解释。',left:['VPC','子网'],right:['VPC 内的地址范围划分','逻辑隔离的虚拟网络'],answer:[1,0],explain:'子网是 VPC 内的地址范围划分，两者处于不同层级。'},
 {id:'ip',course:'network',kind:'choice',title:'真假小侦探',prompt:'小羊说：“有了私网 IP，就能从公共互联网直接访问。”',options:['说得对','还缺少条件'],answer:1,explain:'私网 IP 本身不提供公网可达性，还要看网络连接与访问控制。'},
 {id:'route',course:'network',kind:'match',title:'功能对对碰',prompt:'路径和权限，别再混在一起。',left:['路由','访问控制'],right:['决定是否允许访问','决定流量下一跳'],answer:[1,0],explain:'路由负责路径选择，访问控制负责权限；两者不能互相替代。'},
 {id:'dns',course:'network',kind:'choice',title:'捉住过度推断',prompt:'DNS 已经解析成功，可以立刻推出哪一项？',options:['应用服务一定正常','域名已经获得解析结果','所有网络端口都已开放'],answer:1,explain:'解析成功只是访问链路的一环，不证明应用、网络和端口全部正常。'},
 {id:'lb',course:'network',kind:'match',title:'功能对对碰',prompt:'把功能交给正确的组件。',left:['负载均衡','健康检查'],right:['按条件检查后端是否可用','在后端之间分配流量'],answer:[1,0],explain:'流量分配与可用性检测相互配合，但不是同一功能。'},
 {id:'bio1',course:'bio',kind:'choice',title:'找到真正的灵感',prompt:'哪一种做法更接近仿生设计的研究思路？',options:['只复制动物的外形','先分析功能机制，再适配工程条件','放大生物结构就直接投产'],answer:1,explain:'仿生设计需要从功能机制中抽象原理，再验证工程适用性。'},
 {id:'bio2',course:'bio',kind:'choice',title:'真假小侦探',prompt:'两个结构外形相似，就能证明它们的功能机制相同。',options:['可以证明','还不能证明'],answer:1,explain:'还要分析材料、环境及作用机制，外形相似不足以得出结论。'},
 {id:'bio3',course:'bio',kind:'choice',title:'补上关键拼图',prompt:'生物结构放大后可能失效，因为面积与体积的变化比例 ______。',options:['完全相同','不同','与尺寸无关'],answer:1,explain:'尺度变化会改变面积、体积及相关物理关系，不能简单等比例搬用。'},
 {id:'bio4',course:'bio',kind:'match',title:'研究步骤找搭档',prompt:'观察和实验各自负责什么？',left:['观察','实验'],right:['检验假设和设计效果','发现现象并提出假设'],answer:[1,0],explain:'观察帮助提出假设，实验用于检验，二者不能省略成同一步。'},
 {id:'bio5',course:'bio',kind:'sequence',title:'把思路串起来',prompt:'按顺序点选，从生物现象走到工程设计。',options:['匹配工程约束','实验验证','分析生物机制','抽象可迁移原理'],answer:[2,3,0,1],explain:'先理解机制，再抽象原理，匹配工程约束，最后验证。'}
];
function gameQuestions(){return games.filter(g=>!state.deleted[g.course]).map(g=>{const c=course(g.course),x=c.concepts.find(x=>x.id===g.id);return {...g,concept:g.id,dimension:x?.dimension||'理解',type:g.title,correct:g.explain,source:x?.source||'记忆星球示例讲义',url:x?.url,objective:true}})}
function gradeGame(q,response){return q.kind==='choice'?response===q.answer:Array.isArray(response)&&response.length===q.answer.length&&Array.from(response).every((v,i)=>v===q.answer[i])}
dailyPool=function(){if(dailyDone())return [];const done=new Set(state.records.filter(r=>r.date===day()).map(r=>r.concept));const plan=state.dailyPlan;if(plan?.version===4&&plan.date===day()&&plan.scope===state.settings.scope)return plan.questions.filter(q=>!done.has(q.concept)&&!state.deleted[q.course]);let qs=gameQuestions().filter(q=>state.settings.scope==='全部课程'||course(q.course).type===state.settings.scope);const score=q=>new Set(state.records.filter(r=>r.concept===q.concept&&r.rating==='yes'&&!r.assisted).map(r=>r.date)).size;qs.sort((a,b)=>score(a)-score(b));const questions=qs.filter(q=>!done.has(q.concept)).slice(0,10);state.dailyPlan={version:4,date:day(),scope:state.settings.scope,questions};save();return questions};
const oldSessionView=sessionView;
sessionView=function(){const s=state.session;if(!s||s.mode!=='daily'||!s.questions[s.index]?.objective){oldSessionView();return}const q=s.questions[s.index];const choice=s.gameResponse??(q.kind==='choice'?null:[]);let task='';if(q.kind==='choice')task=`<div class="game-options">${q.options.map((o,i)=>`<button class="option ${choice===i?'selected':''}" data-action="game-choice" data-id="${i}" ${s.revealed?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>`;if(q.kind==='match')task=`<div class="matching">${q.left.map((l,i)=>`<label class="match-row"><span>${esc(l)}</span>${icon('arrow')}<select aria-label="为${esc(l)}选择解释" data-game-match="${i}" ${s.revealed?'disabled':''}><option value="">选择它的搭档</option>${q.right.map((r,j)=>`<option value="${j}" ${choice[i]===j?'selected':''}>${esc(r)}</option>`).join('')}</select></label>`).join('')}</div>`;if(q.kind==='sequence')task=`<div class="sequence-track">${choice.length?choice.map((v,i)=>`<span>${i+1}. ${esc(q.options[v])}</span>`).join('<b>→</b>'):'<span class="muted">你的思路会依次出现在这里</span>'}</div><div class="game-options">${q.options.map((o,i)=>`<button class="option" data-action="game-sequence" data-id="${i}" ${choice.includes(i)||s.revealed?'disabled':''}>${esc(o)}</button>`).join('')}</div>${!s.revealed?'<button class="btn text" data-action="game-reset">重新排列</button>':''}`;const ready=q.kind==='choice'?Number.isInteger(choice):choice.length===q.answer.length&&Array.from(choice).every(Number.isInteger);$('#content').innerHTML=`<div class="session"><div class="session-top"><button class="back" data-action="leave-session">${icon('back')}保存并返回</button><span class="tag">小羊的每日挑战</span></div><h2>动动脑，点亮一颗宝石。</h2><div class="session-top" style="margin-top:22px"><span class="muted">已答 ${s.index} / ${s.questions.length} 题</span><span>已答时间 <b id="timer">${fmt(s.seconds)}</b>　<button class="btn" data-action="pause">${s.paused?'继续':'暂停'}</button></span></div><div class="progress"><i style="width:${s.index/s.questions.length*100}%"></i></div>${s.paused?'<div class="panel paused"><h2>小羊帮你收好了进度。</h2><p>计时已暂停。</p><button class="btn primary" data-action="pause">继续挑战</button></div>':`<section class="panel question-panel game-panel"><span class="tag">${q.title}</span><h2>${esc(q.prompt)}</h2>${task}${s.revealed?`<div class="answer ${s.rating==='yes'?'':'game-repair'}"><strong>${s.rating==='yes'?'答对了，这颗宝石亮起来了！':'找到一个小盲点，也有收获。'}</strong><p>${esc(q.explain)}</p><small>来源：${esc(q.source)}</small></div><p class="notes">客观题结果仅记录辨认与关联练习，不等同于无提示回忆。</p>`:''}<div class="session-actions"><span class="muted">${s.revealed?'先理解，再继续。':'不用打字，选一选、连一连。'}</span><button class="btn primary" data-action="${s.revealed?'game-next':'game-check'}" ${!ready&&!s.revealed?'disabled':''}>${s.revealed?(s.index===s.questions.length-1?'收好今天的宝石':'下一关'):'确认选择'} ${icon('arrow')}</button></div></section>`}</div>`};
const oldNext=next;
next=function(){const s=state.session;if(s?.mode!=='daily'||!s.questions[s.index]?.objective){oldNext();return}if(!s.revealed||s.paused)return;const q=s.questions[s.index],response=s.gameResponse;const answer=q.kind==='choice'?q.options[response]:q.kind==='match'?q.left.map((l,i)=>l+' → '+q.right[response[i]]).join('；'):response.map(i=>q.options[i]).join(' → ');const r={id:s.id+'-'+s.index,session:s.id,date:day(),at:new Date().toISOString(),course:q.course,concept:q.concept,dimension:q.dimension,prompt:q.prompt,answer,rating:s.rating,assisted:false,mode:'daily',objective:true,seconds:s.seconds};if(!state.records.some(x=>x.id===r.id))state.records.push(r);s.results.push(r);s.index++;s.gameResponse=undefined;s.revealed=false;s.rating=null;if(s.index===s.questions.length){const total=s.questions.length,correct=s.results.filter(r=>r.rating==='yes').length;state.dailyCompleted=day();state.session=null;save();page='growth';layout();modal('宝石收好，今天完成',`<div class="result"><div class="result-icon">${icon('star')}</div><h2>${correct} / ${total} 道趣味题答对</h2><p>辨认与关联的练习已经记下。明天重新安排，不留欠账。</p><button class="btn primary full" data-action="close">今天到这里</button></div>`)}else{save();sessionView()}};
const originalEvidence=evidence;
evidence=function(c){const rs=state.records.filter(r=>r.course===c.id&&r.rating==='yes'&&!r.assisted&&!r.objective);return new Set(rs.map(r=>r.concept)).size};
const originalGrowth=growth;
growth=function(){originalGrowth();const count=state.records.filter(r=>r.objective).length;$('#content').insertAdjacentHTML('beforeend',`<div class="banner" style="margin-top:24px"><div><h3>宝石小挑战</h3><p>${count} 次趣味练习 · ${state.records.filter(r=>r.objective&&r.rating==='yes').length} 次答对。与独立回忆记录分开展示。</p></div>${icon('star')}</div>`)};
document.addEventListener('change',e=>{if(e.target.matches('[data-game-match]')){const s=state.session;if(!s||s.revealed)return;s.gameResponse=s.gameResponse||[];s.gameResponse[Number(e.target.dataset.gameMatch)]=e.target.value===''?null:Number(e.target.value);save();sessionView()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='recent-folder'){folder=id;page='recent';layout()}if(a==='complete-course'){setCourseStatus(id,'completed');folder=null;layout();toast('已学完，课程保留在课程库中。')}if(a==='reopen-course'){setCourseStatus(id,'learning');page='recent';folder=null;layout();toast('课程已重新加入最近在学。')}if(a==='read-link')readerModal(id,Number(b.dataset.index));if(a==='capture-preview'){const cp=course(id).links[Number(b.dataset.index)].capture;modal(cp.title,`<p>覆盖范围：${esc(cp.coverage)}</p><div class="source-text" style="margin-top:15px">${esc(cp.text)}</div>`,true)}const s=state.session;if(!s||s.mode!=='daily')return;const q=s.questions[s.index];if(!q?.objective||s.paused)return;if(a==='game-choice'&&!s.revealed){s.gameResponse=Number(id);save();sessionView()}if(a==='game-sequence'&&!s.revealed){s.gameResponse=s.gameResponse||[];if(!s.gameResponse.includes(Number(id)))s.gameResponse.push(Number(id));save();sessionView()}if(a==='game-reset'&&!s.revealed){s.gameResponse=[];save();sessionView()}if(a==='game-check'&&!s.revealed){const response=s.gameResponse;if(q.kind==='choice'?!Number.isInteger(response):!Array.isArray(response)||response.length!==q.answer.length||!Array.from(response).every(Number.isInteger))return;s.rating=gradeGame(q,response)?'yes':'no';s.revealed=true;save();sessionView()}if(a==='game-next')next()});
