newCourse=function(title,type,links,files,headings){const c=createCourseBeforeDirectory(title,type,links,files,headings);if(directoryDraft){for(const l of c.links){const chapter=directoryDraft.chapters.find(x=>x.url===l.url);if(chapter){l.title=chapter.title;l.section=chapter.section}}save()}return c};
const importBeforeDirectory=importModal;
importModal=function(){directoryDraft=null;importBeforeDirectory();$('#course-links').insertAdjacentHTML('afterend','<button type="button" class="btn green" id="detect-directory" style="margin-top:10px">识别 B 站分集目录</button><p class="notes">分 P 视频或合集可尝试从一集识别。目录不等于字幕；识别失败也能先保存课程入口。</p><div id="directory-result" role="status"></div>');$('#detect-directory').onclick=async()=>{const b=$('#detect-directory'),out=$('#directory-result');const raw=$('#course-links').value.split(/\r?\n/).map(x=>x.trim()).find(Boolean);if(!raw){out.textContent='请先粘贴课程中任意一集的完整 B 站视频链接。';return}b.disabled=true;out.textContent='正在识别分集目录…';try{const response=await fetch('/api/bilibili?url='+encodeURIComponent(raw));const data=await response.json();if(!response.ok)throw Error(data.error||'目录读取失败。');if(!Array.isArray(data.chapters)||!data.chapters.length)throw Error('未找到分集目录。');directoryDraft=data;out.innerHTML=`<div class="directory-preview"><strong>${esc(data.title)} · ${data.chapters.length} 节</strong><p class="notes">${esc(data.coverage)}</p><label class="directory-all"><input type="checkbox" id="directory-all" checked> 全选章节</label><div class="directory-list">${data.chapters.map((x,i)=>`<label><input type="checkbox" class="chapter-check" value="${i}" checked><span>${i+1}. ${esc(x.title)}</span></label>`).join('')}</div><button type="button" class="btn primary" id="use-directory">使用选中的章节</button></div>`;$('#directory-all').onchange=e=>document.querySelectorAll('.chapter-check').forEach(x=>x.checked=e.target.checked);$('#use-directory').onclick=()=>{const chapters=[...document.querySelectorAll('.chapter-check:checked')].map(x=>data.chapters[Number(x.value)]);if(!chapters.length){toast('至少选择一节课程。');return}$('#course-links').value=chapters.map(x=>x.url).join('\n');if(!$('#course-name').value.trim())$('#course-name').value=data.title.slice(0,60);out.innerHTML=`<p class="directory-success">已选 ${chapters.length} 节，点击下方创建课程即可。</p>`}}catch(e){out.textContent=(e.message||'目录识别失败。')+' 你可以先保存这一个入口链接。'}finally{b.disabled=false}}};

