document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,a=b.dataset.action;if(a==='delete-course'){const c=course(id);modal('删除这门课程？',`<h3>${esc(c.title)}</h3><p style="margin-top:12px">${c.links?.length||0} 个链接 · ${c.files?.length||0} 份文件</p><p style="margin-top:12px">将从学习和复习书架移出。资料与历史记录保留，可在课程库的“已删除课程”中恢复。</p><div class="rating"><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="confirm-delete" data-id="${id}">移入已删除课程</button></div>`)}if(a==='confirm-delete'){trashCourse(id);close();folder=null;if(page==='session')page='review';layout();toast('课程已移除，可在课程库恢复。')}if(a==='trash')showTrash();if(a==='restore-course'){restoreCourse(id);layout();showTrash();toast('课程已恢复。')}});
