// Evidence score v1: objective, unassisted answers only; one latest answer per day.
function masteryOf(c){
 const points=c.concepts.map(k=>{const byDay=new Map();for(const r of state.records){if(r.course===c.id&&r.concept===k.id&&r.objective===true&&!r.assisted&&['yes','no'].includes(r.rating)&&/^\d{4}-\d{2}-\d{2}$/.test(r.date||''))byDay.set(r.date,r)}
 const attempts=[...byDay.values()].sort((a,b)=>a.date.localeCompare(b.date)).slice(-3);const weight=attempts.reduce((n,r,i)=>n+i+1,0);const score=weight?Math.round(attempts.reduce((n,r,i)=>n+(r.rating==='yes'?100:0)*(i+1),0)/weight):null;
 return {id:k.id,title:k.title,score,attempts,level:score===null?'未评估':attempts.length<2?'待复测':score>=80?'较稳固':score>=60?'待巩固':'薄弱'};});
 const tested=points.filter(p=>p.score!==null);return {points,tested:tested.length,total:points.length,coverage:points.length?Math.round(tested.length/points.length*100):0,score:tested.length?Math.round(tested.reduce((n,p)=>n+p.score,0)/tested.length):null};
}
let masterySelected=null;
const abilityMap=[{title:'容器运行与数据管理',refs:[['docker','image'],['docker','lifecycle'],['docker','storage']]},{title:'网络访问排查',refs:[['network','ip'],['network','route'],['network','dns'],['network','lb']]},{title:'云上方案基础',refs:[['docker','isolation'],['network','vpc'],['network','route']]},{title:'机制分析与验证',refs:[['bio','bio1'],['bio','bio2'],['bio','bio3'],['bio','bio4'],['bio','bio5']]}];
function masteryRules(){modal('掌握评价规则 · v1',`<p>这是可复算的学习证据指标，尚未经过测量学验证，不等于工作能力认证。</p><div class="divider"></div><h3>1. 什么回答计分</h3><p>只计有明确答案的客观题、首次提交且未获得提示的结果：答对 100，答错 0。简答自评、看答案、导入资料和练习次数不产生分数。</p><h3>2. 知识点如何计算</h3><p>同一知识点每天仅取最后一次有效提交，最近三个不同日期从旧到新按 1、2、3 加权；不足三天按 1 或 1、2 计算。总分 = Σ（结果 × 权重）÷ Σ权重，四舍五入。例如三天结果为对、错、对：分数为 (100×1+0×2+100×3)÷6 = 67。</p><h3>3. 分数必须与证据一起看</h3><p>没有有效回答：未评估。仅一天证据：待复测，不标为稳固。两天及以上：80–100 较稳固，60–79 待巩固，0–59 薄弱。展示最近作答日期；不凭空按时间扣分。</p><h3>4. 课程与能力</h3><p>课程分数为已评估知识点的等权平均，覆盖率单独显示，未评估不当作答错。能力网是预设知识关联，显示依赖知识点的证据覆盖与短板，不输出职业能力分。反复答同一道题仍可能产生熟悉效应，后续需用等价变式与应用题验证迁移。</p>`,true)}
growth=function(){const list=courses();if(!list.some(c=>c.id===masterySelected))masterySelected=list[0]?.id;const selected=list.find(c=>c.id===masterySelected);const m=selected?masteryOf(selected):null;
 $('#content').innerHTML=heading('','我的收获','',`<button class="btn" data-action="mastery-rules">评价规则</button>`)+`<div class="mastery-layout"><section class="panel"><h3>课程掌握</h3><div class="mastery-courses">${list.map(c=>{const a=masteryOf(c);return `<button class="mastery-course ${c.id===masterySelected?'selected':''}" data-action="mastery-select" data-id="${c.id}"><strong>${esc(c.title)}</strong><span>${a.score===null?'未评估':a.score+' 分'} <small>已测部分</small></span><div class="progress"><i style="width:${a.score??0}%"></i></div><small>覆盖 ${a.tested} / ${a.total} 个知识点 · ${a.coverage}%</small></button>`}).join('')||'<p>还没有课程。</p>'}</div></section><section class="panel"><div class="section-title"><h3>${selected?esc(selected.title):'知识点详情'}</h3><span class="tag">${m?m.coverage:0}% 已评估</span></div><p class="notes">展开知识点，查看每一分的来源。未评估不代表薄弱。</p>${m?.points.length?m.points.slice().sort((a,b)=>(a.score??101)-(b.score??101)).map(p=>`<details class="mastery-point"><summary><span>${esc(p.title)}</span><b class="mastery-${p.level==='薄弱'?'weak':p.level==='较稳固'?'strong':'pending'}">${p.score===null?'—':p.score+' 分'} · ${p.level}</b></summary><div class="progress"><i style="width:${p.score??0}%"></i></div>${p.attempts.length?`<p class="notes">最近证据：${p.attempts.at(-1).date} · ${p.attempts.length} 个日期</p><ol>${p.attempts.map((r,i)=>`<li>${r.date}：${r.rating==='yes'?'答对 100':'答错 0'} × 权重 ${i+1}<br><small>${esc(r.prompt||'历史客观题记录')}</small></li>`).join('')}</ol><p>加权结果：${p.score} 分</p>`:'<p class="notes">还没有可用于计分的客观题记录。</p>'}</details>`).join(''):'<div class="empty">课程框架尚未确认，暂不评分。</div>'}${selected?.concepts.length?`<button class="btn green" data-action="daily">用每日挑战检验一下</button>`:''}</section></div><section class="panel" style="margin-top:24px"><div class="section-title"><h3>我的能力网</h3><span class="tag">知识支撑关系 · 示例框架</span></div><p class="notes">课程知识如何共同支撑能力；节点可查看课程。亮起表示已有学习证据，不代表已胜任岗位。</p><div class="ability-grid">${abilityMap.map(a=>{const refs=a.refs.map(([id,k])=>{const c=list.find(c=>c.id===id);return c?{c,p:masteryOf(c).points.find(p=>p.id===k)}:null}).filter(r=>r?.p);const known=refs.filter(r=>r.p.score!==null).length;return `<article class="ability-node"><h3>${a.title}</h3><small>${known} / ${a.refs.length} 个支撑点已有证据</small><div class="ability-branches">${refs.map(({c,p})=>`<button class="ability-link ${p.level==='较稳固'?'solid':''}" data-action="mastery-select" data-id="${c.id}">${esc(c.title)} → ${esc(p.title)}<small>${p.level}${p.score===null?'':' · '+p.score+' 分'}</small></button>`).join('')||'<p class="notes">相关课程尚未加入。</p>'}</div></article>`}).join('')}</div></section><details class="panel" style="margin-top:24px"><summary>历史学习记录 · ${state.records.length} 条</summary><button class="btn text" data-action="export">导出记录</button>${state.records.slice(-20).reverse().map(r=>`<div class="history-row"><div>${esc(r.prompt)}<small>${esc(course(r.course)?.title)} · ${esc(r.date)} · ${r.objective?'客观题':'自评记录（不计分）'}</small></div></div>`).join('')}</details>`;
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='mastery-rules')masteryRules();if(b.dataset.action==='mastery-select'){masterySelected=b.dataset.id;growth()}});
